$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Drawing
$root=Split-Path -Parent $PSScriptRoot;$mapRoot=Join-Path $root 'src\KuroganesEcho.Core\Content\Tiled\Maps';$env=[System.Drawing.Bitmap]::new((Join-Path $root 'src\KuroganesEcho.Core\Content\Tiled\Tilesets\Act_03_Environment.png'));$scale=4;$w=320;$h=24
function Tile-Bitmap([int]$gid,[bool]$castleMap){if($castleMap){$local=$gid-1;$r=[int][Math]::Floor($local/20);$c=[int]($local%20);$f=Join-Path $root ("src\KuroganesEcho.Core\Content\Tiled\Tilesets\Castle\tile_r$('{0:D2}'-f$r)_c$('{0:D2}'-f$c)_$('{0:D3}'-f$local).png");return @([System.Drawing.Bitmap]::new($f),[System.Drawing.Rectangle]::new(0,0,16,16))};if($gid -le 300){$local=$gid-1;$src=[System.Drawing.Rectangle]::new(($local%20)*16,[Math]::Floor($local/20)*16,16,16);return @($env,$src)}$local=$gid-301;$r=[int][Math]::Floor($local/20);$c=[int]($local%20);$f=Join-Path $root ("src\KuroganesEcho.Core\Content\Tiled\Tilesets\Env\tile_r$('{0:D2}'-f$r)_c$('{0:D2}'-f$c)_$('{0:D3}'-f$local).png");return @([System.Drawing.Bitmap]::new($f),[System.Drawing.Rectangle]::new(0,0,16,16))}
foreach($mapPath in Get-ChildItem $mapRoot -Filter 'Act_03_*.tmx'){$m=[xml](Get-Content -Raw $mapPath.FullName);$castleMap=$mapPath.BaseName -eq 'Act_03_C';$out=[System.Drawing.Bitmap]::new($w*$scale,$h*$scale,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[System.Drawing.Graphics]::FromImage($out);$g.Clear([System.Drawing.Color]::FromArgb(255,21,41,74));$g.InterpolationMode=[System.Drawing.Drawing2D.InterpolationMode]::NearestNeighbor;$g.PixelOffsetMode=[System.Drawing.Drawing2D.PixelOffsetMode]::Half;foreach($layer in @($m.map.layer)){$b=[Convert]::FromBase64String(($layer.data.'#text' -replace '\s',''));for($i=0;$i -lt $w*$h;$i++){$gid=[BitConverter]::ToUInt32($b,$i*4);if($gid -eq 0){continue};$pair=Tile-Bitmap $gid $castleMap;$bmp=$pair[0];$src=$pair[1];$dst=[System.Drawing.Rectangle]::new(($i%$w)*$scale,[Math]::Floor($i/$w)*$scale,$scale,$scale);$g.DrawImage($bmp,$dst,$src,[System.Drawing.GraphicsUnit]::Pixel);if($bmp -ne $env){$bmp.Dispose()}}};$g.Dispose();$out.Save((Join-Path $PSScriptRoot ($mapPath.BaseName+'_final_preview.png')),[System.Drawing.Imaging.ImageFormat]::Png);$out.Dispose()}
$env.Dispose()
